export function withFile(
  snapshot: RepositorySnapshot,
  path: string,
  content: string
): RepositorySnapshot {
  return {
    ...snapshot,
    files: [
      ...snapshot.files.filter((file) => file.path !== path),
      { path, content }
    ]
  };
}
